(function(){
  const st = window.__store.getState();
  const fp = st.floorPlan;
  const walls = fp.walls; const byId = new Map(walls.map(w => [w.id, w]));
  const ext = fp.extent || [12.55, 9.25];
  const cx = ext[0] / 2, cz = ext[1] / 2;
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
  const openingTransform = (op) => {
    const wall = byId.get(op.wallId); if (!wall) return null;
    const dx = wall.end[0] - wall.start[0], dz = wall.end[1] - wall.start[1];
    const len = Math.hypot(dx, dz); if (len < 1e-6) return null;
    const ux = dx / len, uz = dz / len;
    const c = op.offset + op.width / 2;
    const wx = wall.start[0] + ux * c, wz = wall.start[1] + uz * c;
    let rotation = -Math.atan2(dz, dx);
    const nx = -uz, nz = ux;
    if ((cx - wx) * nx + (cz - wz) * nz < 0) rotation += Math.PI;
    return { position: [wx, wz], rotation };
  };
  const items = st.items.slice();
  // Nudge the default fridge east so it clears the SY/kitchen doorway (it ships
  // flush to the kitchen SW corner, right at the pet-gate opening — occludes it).
  const fridge = items.find(i => i.id === 'default-k-fridge');
  if (fridge) fridge.position = [fridge.position[0] + 1.35, fridge.position[1]];
  // 1. CMF mesh screen on EVERY window.
  for (const op of fp.openings) {
    if (op.kind !== 'window') continue;
    const t = openingTransform(op); if (!t) continue;
    items.push({ id: 'mesh-' + op.id, defId: 'window-mesh-screen', position: t.position, rotation: t.rotation, props: { width: clamp(op.width + 0.06, 0.4, 3.4), sillY: clamp(op.sill, 0, 2.4), topY: clamp(op.head, 0.3, 3.2), density: 'fine' } });
  }
  // 2. Pet gate on the kitchen / service-yard door.
  const door = fp.openings.find(o => o.id === 'door-serviceYard') || fp.openings.find(o => o.kind === 'door');
  if (door) {
    const t = openingTransform(door);
    if (t) { items.push({ id: 'gate-' + door.id, defId: 'pet-gate', position: t.position, rotation: t.rotation, props: { width: clamp(door.width, 0.6, 1.4), height: 1.0, style: 'mesh' } }); window.__gate = { pos: t.position }; }
  }
  // 3. Living/Dining: cat wall run (north wall) + cat tree + dog bed + feeder.
  const rooms = new Map(fp.rooms.map(r => [r.id, r]));
  const ld = rooms.get('livingDining');
  if (ld) {
    const ox = ld.origin[0], oz = ld.origin[1], W = ld.width, D = ld.depth;
    const wz = oz + 0.14; // just inside the north wall
    items.push({ id: 'cat-wall-shelf-show', defId: 'cat-wall-shelf', position: [ox + 0.9, wz], rotation: 0, props: { mountHeight: 1.0 } });
    items.push({ id: 'cat-wall-steps-show', defId: 'cat-wall-steps', position: [ox + 2.0, wz], rotation: 0, props: { mountHeight: 0.8 } });
    items.push({ id: 'cat-wall-bridge-show', defId: 'cat-wall-bridge', position: [ox + 3.2, wz], rotation: 0, props: { span: 1.2, mountHeight: 1.7 } });
    items.push({ id: 'cat-tree-show', defId: 'cat-tree', position: [ox + 0.55, oz + 0.7], rotation: 0.6, props: { tiers: 4, height: 1.6 } });
    items.push({ id: 'dog-bed-show', defId: 'pet-bed', position: [ox + 3.4, oz + 0.85], rotation: 3.14, props: { size: 0.8, shape: 'round' } });
    items.push({ id: 'feeder-show', defId: 'pet-feeding-station', position: [ox + 3.5, oz + 1.7], rotation: 3.14, props: { bowls: '2' } });
    window.__ld = { cx: ox + W * 0.35, cz: oz + 0.9 };
  }
  // 4. Service Yard: litter cabinet + dog cooling mat.
  const sy = rooms.get('serviceYard');
  if (sy) {
    const ox = sy.origin[0], oz = sy.origin[1], W = sy.width, D = sy.depth;
    items.push({ id: 'litter-cabinet-show', defId: 'litter-cabinet', position: [ox + 0.55, oz + D - 0.45], rotation: 0, props: { entrySide: 'right' } });
    items.push({ id: 'litter-box-show', defId: 'litter-box', position: [ox + 1.6, oz + D - 0.4], rotation: 0, props: { style: 'covered' } });
    window.__sy = { cx: ox + W * 0.4, cz: oz + D * 0.55 };
  }
  st.setItems(items);
})()
